from rcb_client import Robot
import numpy as np
r=Robot(); o=r.get_obs(cameras=['robot0_agentview_center'],video='none'); p=np.asarray(o.meta['proprio']['now'],float); q=p[4:11].copy(); print('q',q,'ee',p[26:29])
def act(qt,n):
 row=np.zeros(13); row[:7]=qt; row[7]=-1; row[12]=-1
 return r.submit('joint_position',np.tile(row,(n,1)),video='none')
for j in [1,2,3,4,5,6]:
 t=q.copy(); t[j]+=.08; a=act(t,10); print(j,'plus ee',np.round(a.meta['proprio']['now'][26:29],5),'q',np.round(a.meta['proprio']['now'][4:11],3)); act(q,10)
